create table MB_PROD_GROUP (PROD_TYPE VARCHAR(20) not null  ,PROD_SUB_TYPE VARCHAR(20) not null  ,SEQ_NO VARCHAR(50) null  ,DEFAULT_PROD_FLAG VARCHAR(1) null  ,ACCT_CLASS VARCHAR(1) null  ,RATIO DECIMAL(17,2) null  ,COMPANY VARCHAR(20) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(PROD_TYPE,PROD_SUB_TYPE,COMPANY));